from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    # Infer the smallest periodic tile from the non-zero clues; occasional
    # repeated clue rows can be exceptions, so choose the tile with fewest
    # disagreements, breaking ties by tile area.
    for ph in range(1, h + 1):
        for pw in range(1, w + 1):
            groups = {}
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    if v:
                        groups.setdefault((r % ph, c % pw), []).append(v)
            score = sum(len(vals) - max(Counter(vals).values()) for vals in groups.values())
            cand = (score, ph * pw, ph, pw, groups)
            if best is None or cand[:2] < best[:2]:
                best = cand
    _, _, ph, pw, groups = best
    tile = {k: Counter(v).most_common(1)[0][0] for k, v in groups.items()}
    # Unknown tile positions are filled by the most common known clue color.
    fallback = Counter(v for row in grid for v in row if v).most_common(1)[0][0]
    out = [[tile.get((r % ph, c % pw), fallback) for c in range(w)] for r in range(h)]
    # Existing marks remain fixed, including any repeated exceptional stripe.
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                out[r][c] = grid[r][c]
    return out
